// Создаёт коллекцию Qdrant, если её нет. Один выход — независимо от исхода.
let status = 'exists';
try {
  await this.helpers.httpRequest({ method: 'GET', url: 'http://qdrant:6333/collections/invoice_items', json: true });
} catch (e) {
  try {
    await this.helpers.httpRequest({
      method: 'PUT',
      url: 'http://qdrant:6333/collections/invoice_items',
      body: { vectors: { size: 1024, distance: 'Cosine' } },
      json: true
    });
    status = 'created';
  } catch (e2) {
    throw new Error('Qdrant недоступен, коллекцию создать не удалось: ' + (e2.cause && e2.cause.message ? e2.cause.message : e2.message));
  }
}
return { json: { collection: 'invoice_items', status: status } };

// Собираем тексты для bge-m3.
// Наименования кладём как есть (документный режим); query-префикс
// использует матчер (Invoice-006) при поиске SKU.
const rows = $input.all().map(x => x.json);
if (!rows.length) return [];
return [{ json: {
  items: rows.map(r => ({ item_id: r.item_id, file_name: r.file_name, line_no: r.line_no, item_name: r.item_name })),
  texts: rows.map(r => String(r.item_name).slice(0, 2000))
} }];

// Собираем точки Qdrant и payload для записи в кэш.
// id точки — детерминированный UUID v5 от (file_name, line_no):
// переобработка файла перезаписывает те же точки, сирот не возникает
// (задача 002, решение владельца 2026-10-07).
const crypto = require('crypto');
function uuid5(text) {
  const h = crypto.createHash('sha1').update(text).digest();
  h[6] = (h[6] & 0x0f) | 0x50;
  h[8] = (h[8] & 0x3f) | 0x80;
  const hex = h.toString('hex');
  return hex.slice(0, 8) + '-' + hex.slice(8, 12) + '-' + hex.slice(12, 16) + '-' + hex.slice(16, 20) + '-' + hex.slice(20, 32);
}
const src = $('Prepare texts').first().json;
const embs = $json.embeddings || [];
if (!Array.isArray(embs) || embs.length !== src.items.length) {
  throw new Error('EMBED_MISMATCH: ожидалось ' + src.items.length + ' векторов, пришло ' + embs.length);
}
const points = src.items.map((it, i) => ({
  id: uuid5('item:' + it.file_name + ':' + it.line_no),
  vector: embs[i],
  payload: { file_name: it.file_name, line_no: it.line_no, item_id: it.item_id, item_name: it.item_name }
}));
const cachePayload = { keys: src.items.map(it => ({ f: it.file_name, l: it.line_no })), model: 'bge-m3' };
return { json: {
  points: points,
  cache_sql: JSON.stringify(cachePayload).replace(/'/g, "''")
} };
